const body = $json.body ?? $json;

const binaryKeys = $binary ? Object.keys($binary) : [];

let source = null;
let sourceName = null;

const preferredKeys = ['data', 'data0', 'image', 'image0', 'file', 'upload'];

for (const key of preferredKeys) {
  if ($binary?.[key]) {
    sourceName = key;
    source = $binary[key];
    break;
  }
}

if (!source && binaryKeys.length > 0) {
  sourceName = binaryKeys[0];
  source = $binary[sourceName];
}

if (!source) {
  throw new Error(
    'Nenhuma imagem foi recebida pelo webhook. Campos binários encontrados: ' +
    (binaryKeys.join(', ') || 'nenhum')
  );
}

const allowed = [
  'image/jpeg',
  'image/jpg',
  'image/png',
  'image/webp'
];

const mimeType = String(source.mimeType || '').toLowerCase();

if (!allowed.includes(mimeType)) {
  throw new Error(
    'Formato de imagem não suportado: ' +
    (mimeType || 'mimeType desconhecido') +
    '. Formatos aceitos: JPEG, PNG e WEBP.'
  );
}

const pedido = String(
  body?.pedido ??
  body?.text ??
  body?.prompt ??
  $json.pedido ??
  $json.text ??
  ''
).trim();

const runId = `cena-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

const arquivo = {
  nome: source.fileName || `rascunho-${runId}`,
  mimeType,
  tamanho_bytes: Number(source.fileSize || 0)
};

return {
  json: {
    runId,
    timestamp: new Date().toISOString(),
    pedido,
    campo_original: sourceName,
    campo_normalizado: 'data',
    arquivo,
    imagem_base64: source.data,
    imagem_referencia_disponivel: true
  },
  binary: {
    data: source
  }
};

const response = $json || {};
const original = $node['Normalizar Upload → data'].json;
const binary = $node['Normalizar Upload → data'].binary;

function findText(obj) {
  if (!obj) return '';

  if (typeof obj === 'string') return obj.trim();

  if (Array.isArray(obj)) {
    const parts = obj.map(findText).filter(Boolean);
    return parts.join('\n').trim();
  }

  if (typeof obj === 'object') {
    const keys = [
      'text',
      'ocr_text',
      'texto',
      'result',
      'output',
      'content',
      'message'
    ];

    for (const key of keys) {
      if (obj[key] !== undefined) {
        const value = findText(obj[key]);
        if (value) return value;
      }
    }
  }

  return '';
}

const ocrText = findText(response);

return {
  json: {
    ...original,
    ocr_text: ocrText,
    ocr_raw: response,
    ocr_status: ocrText ? 'sucesso' : 'sem_texto_detectado',
    referencia_visual: true
  },
  binary: {
    data: binary.data
  }
};

function extract(value) {
  if (!value) return '';

  if (typeof value === 'string') return value.trim();

  if (Array.isArray(value)) {
    for (const v of value) {
      const x = extract(v);
      if (x) return x;
    }
  }

  if (typeof value === 'object') {
    const keys = [
      'content',
      'text',
      'output',
      'response',
      'message',
      'analise_visual',
      'analysis'
    ];

    for (const key of keys) {
      if (value[key] !== undefined) {
        const x = extract(value[key]);
        if (x) return x;
      }
    }
  }

  return '';
}

const analise = extract($json);
const contexto = $node['Preparar Resultado OCR'].json;
const binary = $node['Preparar Resultado OCR'].binary;

if (!analise) {
  throw new Error('Vision não retornou uma especificação técnica utilizável.');
}

if (!binary?.data) {
  throw new Error('A imagem original foi perdida antes da etapa Vision.');
}

return {
  json: {
    runId: contexto.runId,
    timestamp: new Date().toISOString(),
    pedido: contexto.pedido,
    ocr_text: contexto.ocr_text || '',
    analise_visual: analise,
    especificacao_tecnica: analise,
    arquivo: contexto.arquivo,
    imagem_referencia_disponivel: true
  },
  binary: {
    data: binary.data
  }
};

