const output = String(
  $json.output ??
  $json.text ??
  $json.response ??
  ''
).trim();

if (!output) {
  throw new Error('O Agente Diretor de Cena não produziu um prompt.');
}

const contexto = $node['Preparar Contexto Técnico'].json;
const binary = $node['Preparar Contexto Técnico'].binary;
const identificacao = $node['AGENT - Identificar Móvel'].json.output || '';

if (!binary?.data) {
  throw new Error('O rascunho original não está disponível para o GPT Image.');
}

return {
  json: {
    sucesso: true,
    etapa: 'prompt_imagem',
    runId: contexto.runId,
    timestamp: new Date().toISOString(),
    pedido: contexto.pedido,
    ocr_text: contexto.ocr_text,
    especificacao_tecnica: contexto.especificacao_tecnica,
    analise_visual: contexto.analise_visual,
    identificacao_movel: identificacao,
    image_prompt: output,
    referencia_visual: true,
    referencia_campo_binario: 'data'
  },
  binary: {
    data: binary.data
  }
};

const response = $json;
const contexto = $node['Preparar Prompt GPT Image'].json;

const result = Array.isArray(response.data) ? response.data[0] : null;

if (!result) {
  throw new Error(
    'GPT Image não retornou data[0]. Resposta recebida: ' +
    JSON.stringify(response)
  );
}

if (!result.b64_json && !result.url) {
  throw new Error('GPT Image não retornou b64_json nem URL.');
}

if (result.b64_json) {
  return {
    json: {
      sucesso: true,
      codigo: 'IMAGE_GENERATED',
      etapa: 'imagem_gerada',
      runId: contexto.runId,
      timestamp: new Date().toISOString(),
      image_url: null,
      image_mime_type: 'image/png',
      image_file_name: `cena-${contexto.runId}.png`,
      image_prompt: contexto.image_prompt,
      especificacao_tecnica: contexto.especificacao_tecnica,
      identificacao_movel: contexto.identificacao_movel,
      referencia_visual_utilizada: true
    },
    binary: {
      data: {
        data: result.b64_json,
        mimeType: 'image/png',
        fileName: `cena-${contexto.runId}.png`,
        fileExtension: 'png'
      }
    }
  };
}

return {
  json: {
    sucesso: true,
    codigo: 'IMAGE_GENERATED_URL',
    etapa: 'imagem_gerada',
    runId: contexto.runId,
    timestamp: new Date().toISOString(),
    image_url: result.url,
    image_mime_type: 'image/png',
    image_file_name: null,
    image_prompt: contexto.image_prompt,
    especificacao_tecnica: contexto.especificacao_tecnica,
    identificacao_movel: contexto.identificacao_movel,
    referencia_visual_utilizada: true
  }
};
